import Foundation

/// 스토어에 올린 앱마다 QA할 때 볼 전용 항목. 번들 ID로 찾는다(대소문자 무시).
/// 각 앱의 README·문서·소스를 읽고 기능 전체를 도는 리그레션 목록으로 적었다.
/// 기준은 클립키보드 5.1.4 목록이다: 화면·기능·확장·결제·데이터 경로를 빠짐없이 도는 리그레션, 앱 크기에 따라 50~130개.
/// 기본 체크리스트와 겹치는 것은 뺐다.
/// (분류, 제목, 확인 단계, 무엇으로 확인하는가)
typealias CatalogItem = (category: ChecklistCategory, title: String, steps: String, verification: Verification)

enum AppChecklistCatalog {
    static func key(_ bundleID: String) -> String {
        bundleID.trimmingCharacters(in: .whitespaces).lowercased()
    }

    static func items(for bundleID: String) -> [CatalogItem] {
        byKey[key(bundleID)] ?? []
    }

    /// 기본 체크리스트는 모든 앱이 같은 문구를 쓰는 탓에 "가장 흔한 일 하나를 고른다"처럼 두루뭉술해진다.
    /// 앱마다 그 앱의 화면과 흐름으로 바꿔 적어 둔 것이 있으면 세션에서 그것을 보여 준다.
    static func defaultSteps(for bundleID: String) -> [String: String] {
        defaultStepsByKey[key(bundleID)] ?? [:]
    }

    private static let defaultStepsByKey: [String: [String: String]] = Dictionary(
        uniqueKeysWithValues: defaultStepsByBundleID.map { (key($0.key), $0.value) }
    )

    private static let byKey: [String: [CatalogItem]] = Dictionary(
        uniqueKeysWithValues: itemsByBundleID.map { (key($0.key), $0.value) }
    )

    /// 이 항목이 앱의 어느 구역(화면·기능 영역)에 있는가. 세션에서 "지금 어디를 보는지"로 쓴다.
    static func area(of title: String, for bundleID: String) -> String? {
        areaByKey[key(bundleID)]?[title]
    }

    /// 구역 표시 줄. 다음 구역 표시 전까지의 항목이 이 구역에 든다. 항목 목록에는 나오지 않는다.
    static func section(_ name: String) -> CatalogItem {
        (.custom, sectionPrefix + name, "", .manual)
    }

    private static let sectionPrefix = "\u{1}구역:"

    private static func sectionName(_ line: CatalogItem) -> String? {
        line.title.hasPrefix(sectionPrefix) ? String(line.title.dropFirst(sectionPrefix.count)) : nil
    }

    /// 구역 표시 줄을 걷어 낸 항목만.
    static let itemsByBundleID: [String: [CatalogItem]] = linesByBundleID.mapValues { lines in
        lines.filter { sectionName($0) == nil }
    }

    /// 번들 키 → (항목 제목 → 구역 이름).
    private static let areaByKey: [String: [String: String]] = Dictionary(
        uniqueKeysWithValues: linesByBundleID.map { bundleID, lines in
            var current: String?
            var areas: [String: String] = [:]
            for line in lines {
                if let name = sectionName(line) {
                    current = name
                } else if let current {
                    areas[line.title] = current
                }
            }
            return (key(bundleID), areas)
        }
    )

    /// 항목 줄 사이에 `section(…)` 줄을 끼워 구역(앱의 화면·기능 영역)을 나눈다. 구역은 앱을 쓰는 순서대로 늘어놓는다.
    private static let linesByBundleID: [String: [CatalogItem]] = [
        // StickyPresenter
        "com.leeo.StickyPresenter": [
            section("첫 실행과 메뉴 막대"),
            (.stability, "첫 실행에 사용법 스티키 노트가 하나 뜬다", "앱을 지우고 새로 깐다 → 처음 연다 → 단축키가 적힌 노란 노트 하나가 화면에 뜬다", .manual),
            (.custom, "첫 실행에 사용 가이드 창이 맨 앞에 뜬다", "앱을 지우고 새로 깐다 → 처음 연다 → 사용법 노트 위로 StickyPresenter 사용 가이드 창이 시작하기 주제로 뜬다", .manual),
            (.appearance, "Dock에 아이콘 없이 메뉴 막대에만 산다", "앱을 켠다 → Dock과 메뉴 막대를 함께 본다 → Dock은 비었고 메뉴 막대에 노트 아이콘만 있다", .manual),
            (.platform, "⌘⌃N을 누르면 빈 노트가 새로 뜬다", "Safari 같은 다른 앱을 앞에 둔다 → ⌘⌃N을 누른다 → 글자 없는 새 노트가 뜬다", .manual),
            (.platform, "⌘⌃S·⌘⌃H로 모든 노트가 보였다 숨는다", "노트를 두세 장 띄워 둔다 → ⌘⌃H를 누르면 다 사라진다 → ⌘⌃S를 누르면 그 자리에 다시 나온다", .manual),
            (.custom, "기본 색 메뉴에서 고른 색으로 새 노트가 난다", "메뉴 막대 ▸ 기본 색상에서 분홍을 고른다 → ⌘⌃N을 누른다 → 새 노트가 분홍으로 뜬다", .manual),
            (.stability, "모든 창을 닫아도 앱이 메뉴 막대에 남는다", "노트와 타이머 창을 하나씩 다 닫는다 → 메뉴 막대를 본다 → 노트 아이콘이 그대로 있다", .manual),
            (.platform, "Finder에서 다시 열면 타이머 목록이 뜬다", "앱이 켜진 채로 응용 프로그램에서 StickyPresenter를 다시 연다 → 타이머 창이 앞으로 나온다", .manual),

            section("사용 가이드"),
            (.custom, "도움말 ▸ 사용 가이드로 가이드 창을 다시 연다", "메뉴 막대 ▸ 도움말 ▸ 사용 가이드를 누른다 → 화면을 본다 → 왼쪽에 일곱 주제가 있는 가이드 창이 뜬다", .ui),
            (.custom, "다음을 눌러 일곱 주제를 차례로 넘기고 시작하기로 닫는다", "가이드 창에서 다음을 여섯 번 누른다 → 단축키 주제에서 단추가 시작하기로 바뀐다 → 누르면 창이 닫힌다", .ui),
            (.custom, "단축키 주제에 일곱 단축키가 표로 나온다", "가이드 왼쪽에서 단축키를 누른다 → 표를 본다 → ⌘⌃N부터 ⌘⌃H까지 일곱 줄이 하는 일과 함께 적혀 있다", .ui),
            (.stability, "다른 앱이 차지한 단축키는 다른 앱이 사용 중으로 표시된다", "다른 앱에 ⌘⌃T를 먼저 등록해 둔다 → StickyPresenter를 켜고 가이드 ▸ 단축키를 연다 → ⌘⌃T 줄에 주황 글씨로 다른 앱이 사용 중이 붙는다", .manual),
            (.custom, "도움말 메뉴에서 메일과 인스타그램이 열린다", "메뉴 막대 ▸ 도움말을 연다 → 이메일과 인스타그램 DM을 차례로 누른다 → 메일 앱과 브라우저가 뜬다", .manual),

            section("단축키"),
            (.platform, "Keynote 전체 화면 앞에서 ⌘⌃T가 바로 먹는다", "손쉬운 사용 권한을 주지 않은 채 Keynote 슬라이드쇼를 연다 → ⌘⌃T를 누른다 → 슬라이드 위에서 타이머 위젯이 숨었다 나타난다", .manual),
            (.platform, "⌘⌃T가 타이머 위젯을 감췄다 다시 보인다", "타이머 두 개를 돌린다 → ⌘⌃T를 누르면 위젯 둘이 사라지고 타이머 창은 남는다 → 다시 누르면 위젯이 그 자리에 나온다", .manual),

            section("스티키 노트"),
            (.platform, "전체 화면 Keynote 위에 스티키 노트가 보인다", "노트를 하나 띄운다 → Keynote 슬라이드쇼를 전체 화면으로 시작한다 → 노트가 슬라이드 위에 남는다", .manual),
