            (.custom, "⌘⌃V로 클립보드 내용이 새 노트가 된다", "다른 앱에서 글을 복사한다 → 어디서든 ⌘⌃V를 누른다 → 그 글이 담긴 노트가 뜬다", .manual),
            (.appearance, "마우스를 올려야 노트 조절 단추가 나타난다", "노트에서 마우스를 멀리 뗀다 → 단추가 없다 → 노트 위에 올리면 색과 잠금 단추가 나타난다", .manual),
            (.custom, "색 동그라미를 눌러 여섯 색으로 바꾼다", "노트 왼쪽 위 색 동그라미를 누른다 → 뜬 여섯 색 중 초록을 고른다 → 노트 바탕이 초록이 된다", .manual),
            (.custom, "투명도 슬라이더로 노트가 옅어진다", "노트의 회색 반달 단추를 누른다 → 투명도를 왼쪽 끝까지 내린다 → 뒤 화면이 비쳐 보인다", .manual),
            (.custom, "글자 크기 ±로 10pt에서 32pt까지 간다", "노트 오른쪽 위 마이너스를 끝까지 누르면 10에서 멈춘다 → 플러스를 끝까지 누르면 32에서 멈춘다", .unit),
            (.stability, "자물쇠를 채우면 글이 안 고쳐지고 선택만 된다", "노트 오른쪽 위 자물쇠를 누른다 → 본문에 글자를 쳐 본다 → 안 써지고 끌어서 선택만 된다", .manual),
            (.appearance, "아래 줄에 글자 수가 세어져 보인다", "노트에 열 글자를 친다 → 노트 맨 아래 줄을 본다 → 10자로 적히고 지우면 숫자가 준다", .manual),
