            (.stability, "빠진 모니터에 있던 노트가 다음 실행 때 기본 화면 안으로 온다", "외장 모니터에 노트를 옮기고 앱을 끝낸다 → 모니터를 빼고 앱을 연다 → 노트가 맥북 화면 안에 보인다", .manual),
